declare(strict_types=1);require __DIR__.'/app/bootstrap.php';if(is_file(__DIR__.'/app/access_control_v1300.php'))require_once __DIR__.'/app/access_control_v1300.php';require_once __DIR__.'/app/classifieds_v1370.php';$uid=(int)($_GET['user']??0);if($uid<1){http_response_code(404);exit('Seller not found.');}$name=sk1370_user_label($uid);$q=sk1370_db()->prepare("SELECT a.*,c.name category_name FROM classified_ads_v1370 a JOIN classified_categories_v1370 c ON c.id=a.category_id WHERE a.tenant_id=? AND a.user_id=? AND a.status='active' AND a.moderation_status='approved' AND (a.expires_at IS NULL OR a.expires_at>NOW()) ORDER BY CASE WHEN a.featured_until>NOW() THEN 0 ELSE 1 END,a.bump_at DESC,a.id DESC LIMIT 100");$q->execute([sk1370_tid(),$uid]);$ads=$q->fetchAll(PDO::FETCH_ASSOC)?:[];sk1370_shell($name.' · Seller','seller-page');?><section class="seller-profile"><span class="seller-avatar"><?=sk1370_h(strtoupper(substr($name,0,1)))?></span><div><span class="eyebrow">SHAHKOTPK SELLER</span><h1><?=sk1370_h($name)?></h1><p><?=count($ads)?> active local ad<?=count($ads)===1?'':'s'?></p></div></section><section class="cat-strip"><div class="section-title"><div><span>ACTIVE LISTINGS</span><h2>Ads from this seller</h2></div></div><div class="ad-grid"><?php if(!$ads):?><div class="empty">No active ads from this seller.</div><?php else:foreach($ads as $a)sk1370_ad_card($a);endif;?></div></section><?php sk1370_end();
